# Lecture 4, parts 5-6: EBITDA and the leases standard, then net margin, financing costs, the effective tax rate and the capital structure.

# ================================================================ part 5: EBITDA
opener(5, 'EBITDA', 'שאלת החלק: למה אנליסטים מוסיפים בחזרה את הפחת, ומה קרה ל-EBITDA של כל הקמעונאים ב-2019?',
       ['הגדרה ודוגמה', 'למה משתמשים בו, ומה הוא מסתיר', 'תקן החכירות: אותה חנות, EBITDA אחר', 'מסבירים יחד: לפני התקן ואחריו'], 20)

S('d-ebitda', 'EBITDA', 'רווח לפני ריבית, מסים, פחת והפחתות',
  DEF('EBITDA (Earnings Before Interest, Taxes, Depreciation and Amortization)', 'הרווח התפעולי, ועוד הפחת וההפחתות שנוכו בדרך אליו. בעברית: רווח לפני ריבית, מסים, פחת והפחתות.',
      'רווח תפעולי 1,360 ופחת 240: EBITDA של 1,600.', n=1, trm='ebitda')
  + '<div class="row eq2 top">' + RDEF(2, 'שיעור EBITDA', 'EBITDA margin', 'EBITDA', 'מכירות', 'ebitdam')
  + ST(3, '<b class="ct">' + TX('למה מוסיפים את הפחת?') + '</b><p>' + TX('פחת אינו יציאה של מזומן השנה: הכסף יצא כשקנו את המכונה. לכן EBITDA קרוב יותר למזומן שהפעילות מייצרת, ונוח להשוואה בין חברות עם רכוש קבוע ישן וחדש.') + '</p>', cls='card cmp3 okb') + '</div>'
  + BAND('trap', 'אבל המכונה תצטרך החלפה. חברה שמציגה EBITDA גבוה ומתעלמת מההשקעות שהיא חייבת לעשות מציגה תמונה ורודה מדי.', 4), kick='חלק 5 · הגדרה')

S('s-ifrs16', 'תקן החכירות', 'אותה חנות, EBITDA אחר: תקן החכירות',
  '<div class="row eq2 top"><div class="col"><div class="card"><b class="ct">' + TX('עד 2018') + '</b>'
  + ST(1, TX('דמי השכירות של החנויות, 120 בשנה, הם הוצאה תפעולית רגילה. הם יורדים <b>לפני</b> ה-EBITDA.'), 'p') + '</div></div>'
  + '<div class="col"><div class="card"><b class="ct">' + TX('מ-2019, לפי [[lease|IFRS 16]]') + '</b>'
  + ST(2, TX('החנות השכורה נרשמת כנכס, ״זכות שימוש״, וההתחייבות לשלם את השכירות כהתחייבות חכירה.'), 'p')
  + ST(3, TX('במקום דמי שכירות: <b>פחת</b> על הנכס, 100, ו<b>ריבית</b> על ההתחייבות, 30. שניהם יורדים <b>אחרי</b> ה-EBITDA.'), 'p') + '</div></div></div>'
  + BAND('ans', 'התוצאה: אותן חנויות, אותו מזומן לבעל הבית, וה-EBITDA קופץ בכל דמי השכירות, 120. הרווח התפעולי עולה מעט, והרווח הנקי בשנים הראשונות דווקא יורד.', 4)
  + BAND('dg', 'לכן כשמשווים EBITDA של קמעונאי לפני 2019 ואחרי, או בין חברה שבבעלותה החנויות לחברה ששוכרת אותן, בודקים אם המספר כולל את השפעת התקן. חברות רבות מדווחות על EBITDA בשתי הדרכים.', 5), kick='חלק 5 · עיקרון')

_IF = {'A1': 'רשת המעדנים, אלפי ש״ח', 'B1': 'לפני התקן', 'C1': 'אחרי התקן', 'A2': 'מכירות', 'A3': 'הוצאות תפעול בלי שכירות ובלי פחת', 'A4': 'פחת ציוד', 'A5': 'דמי שכירות',
       'A6': 'פחת זכות שימוש', 'A7': 'ריבית על התחייבות החכירה', 'A9': 'EBITDA', 'A10': 'רווח תפעולי', 'A11': 'רווח לפני מס'}
_iff = lambda c: {f'{c}9': f'={c}2-{c}3-{c}5', f'{c}10': f'={c}9-{c}4-{c}6', f'{c}11': f'={c}10-{c}7'}
_IFS = {**_iff('B'), **_iff('C')}
QX('x-ifrs', 'מסבירים יחד', 'רשת המעדנים: אותה שנה, שתי שיטות',
   ['לרשת המעדנים בע״מ מכירות של 2,000 אלפי ש״ח והוצאות תפעול של 1,500, בלי שכירות ובלי פחת. פחת הציוד 100. החנויות שכורות, ודמי השכירות 120 בשנה.',
    'לפי תקן החכירות, במקום דמי השכירות נרשמים פחת על זכות השימוש, 100, וריבית על התחייבות החכירה, 30.', '<b>נדרש:</b> חשבו את ה-EBITDA, את הרווח התפעולי ואת הרווח לפני מס, לפני התקן ואחריו.'],
   'שורות 9 עד 11 בעמודה B, וגוררים לעמודה C.',
   _IF, _IFS, [250, 100, 100], [1], given={'B2': 2000, 'C2': 2000, 'B3': 1500, 'C3': 1500, 'B4': 100, 'C4': 100, 'B5': 120, 'C5': 0, 'B6': 0, 'C6': 100, 'B7': 0, 'C7': 30},
   fmt={f'{c}{r}': 'num0' for c in 'BC' for r in list(range(2, 8)) + [9, 10, 11]}, sty=_HD(),
   hints=['EBITDA: מכירות פחות הוצאות התפעול ופחות השכירות, =B2-B3-B5.', 'רווח תפעולי: =B9-B4-B6. רווח לפני מס: =B10-B7. גוררים לעמודה C.'], remind='=B2-B3-B5',
   steps=[dict(cells={f'{c}{r}': _IFS[f'{c}{r}']}, note=f'{_IF["A" + str(r)]}, {"לפני התקן" if c == "B" else "אחרי התקן"}.') for r in (9, 10, 11) for c in 'BC'],
   qmc=RLIST([('EBITDA', 'מכירות', 'פחות הוצאות תפעול ושכירות'), ('רווח תפעולי', 'EBITDA', 'פחות כל הפחת')]).replace('<i>חלקי</i> פחות', '<i>פחות</i>'),
   note=[('ans', 'לפני: EBITDA 380, רווח תפעולי 280, לפני מס 280. אחרי: 500, 300, 270.', 1),
         ('dg', 'טיפ: שיעור ה-EBITDA קפץ מ-19% ל-25% בלי שום שינוי בעסק. הרווח לפני מס אפילו ירד ב-10, כי הריבית בתחילת החכירה גבוהה.', 2)],
   done='לפני: 380, 280, 280. אחרי: 500, 300, 270.', xtitle='רשת המעדנים: תקן החכירות')

S('w-ifrs', 'מהעולם: רמי לוי', 'מהעולם: רמי לוי מדווחת EBITDA בשתי הדרכים',
  '<div class="row g55 top"><div class="col" style="flex:0 0 600px">'
  + _tb(['רמי לוי, 2025', 'מיליוני ש״ח', 'מההכנסות'], [('EBITDA כפי שדווח, לפי תקן החכירות', '719', '9.18%'), ('EBITDA בלי השפעת התקן', '450', '5.74%'), ('ההפרש: השפעת התקן', '269', '')], hl=(2,))
  + _SRC('מקור: הדוח התקופתי של רמי לוי שיווק השקמה לשנת 2025, דוח הדירקטוריון.') + '</div><div class="col">'
  + BAND('ans', 'אותה רשת, אותה שנה: שיעור EBITDA של 9.2%, או של 5.7%. ההבדל הוא שכר הדירה של הסניפים.', 1)
  + BAND('dg', 'כשמשווים EBITDA בין רשתות, או לשנים שלפני 2019, משווים את המספר בלי השפעת התקן. חברות שמדווחות בשתי הדרכים עושות את העבודה בשבילנו.', 2) + '</div></div>', kick='חלק 5 · מהעולם האמיתי')

MC1('m-ebitda', 'שאלה אחת: EBITDA קפץ', 'רשת קמעונאית מבשרת במצגת למשקיעים: ״ה-EBITDA שלנו עלה ב-30%״. איזו שאלה כדאי לשאול קודם?',
    ['האם העלייה נובעת מהפעילות, או מתקן החכירות ומאירועים חד פעמיים, ומה קרה להשקעות ברכוש קבוע', 'מה שיעור המס', 'כמה עובדים יש ברשת', 'מה היחס השוטף'], 0,
    'EBITDA אינו מוגדר בתקינה, וכל חברה מחשבת אותו קצת אחרת. עלייה חדה יכולה לנבוע ממעבר לשכירות לפי התקן, מרווח הון, או מוויתור על הוצאות שבעצם יחזרו. וגם EBITDA אמיתי לא אומר כמה החברה צריכה להשקיע כדי לשמור על הנכסים.', art='detective')

# ================================================================ part 6: net margin
opener(6, 'שיעור רווח נקי', 'שאלת החלק: מה נשאר לבעלים, ולמה שתי חברות עם אותו רווח תפעולי מגיעות לשורה תחתונה שונה?',
       ['דוגמה, והכלל', 'שיעור מס אפקטיבי', 'מסבירים יחד: הון עצמי מול חוב', 'שאלה אחת: גולמי עולה, נקי עומד'], 25)

S('e-nm', 'דוגמה', 'תבליני המזרח: מה נשאר לבעלים?',
  '<div class="card qstem"><p>' + TX('לתבליני המזרח מכירות 1,000 ורווח תפעולי 120, באלפי ש״ח. הוצאות המימון, ריבית על הלוואה, 20. המסים על ההכנסה 23.') + '</p></div>'
  + ONE([(1, 'רווח לפני מס', '100', 'איך חישבנו', ['רווח תפעולי 120, פחות מימון 20.'], 'אחרי הבנק.'),
         (2, 'רווח נקי', '77', 'איך חישבנו', ['100, פחות מס 23.'], 'אחרי המס: מה שנשאר לבעלים.'),
         (3, 'שיעור רווח נקי', '7.7%', 'איך חישבנו', ['77 חלקי 1,000.'], 'מכל שקל של מכירות, 7.7 אגורות לבעלים.')], 'ap', h=True)
  + '<div class="row eq2 top">' + RDEF(4, 'שיעור רווח נקי', 'Net margin', 'רווח נקי', 'מכירות', 'nm')
  + RDEF(5, 'שיעור מס אפקטיבי', 'Effective tax rate', 'מסים על ההכנסה', 'רווח לפני מס', 'etr') + '</div>'
  + BAND('dg', 'כאן: 23 חלקי 100, כלומר 23%. שיעור אפקטיבי שונה מהשיעור בחוק מסמן משהו: הטבות מס, הפסדים מועברים, או הוצאות שאינן מוכרות למס.', 6), kick='חלק 6 · דוגמה והכלל')

_NM = {'A1': 'שנת 2026, אלפי ש״ח', 'B1': 'אבן הון', 'C1': 'אבן חוב', 'A2': 'מכירות', 'A3': 'רווח תפעולי', 'A4': 'הוצאות מימון', 'A5': 'שיעור מס', 'A7': 'רווח לפני מס', 'A8': 'מסים על ההכנסה',
       'A9': 'רווח נקי', 'A10': 'שיעור רווח תפעולי', 'A11': 'שיעור רווח נקי'}
_nmf = lambda c: {f'{c}7': f'={c}3-{c}4', f'{c}8': f'={c}7*{c}5', f'{c}9': f'={c}7-{c}8', f'{c}10': f'={c}3/{c}2', f'{c}11': f'={c}9/{c}2'}
_NMS = {**_nmf('B'), **_nmf('C')}
QX('x-nm1', 'מסבירים יחד', 'אבן הון מול אבן חוב: אותה פעילות, מימון אחר',
   ['שתי מחצבות זהות: אותן מכירות, 10,000 אלפי ש״ח, ואותו רווח תפעולי, 1,200. אבן הון מומנה בהון עצמי, ואין לה הוצאות מימון. אבן חוב מומנה בהלוואות, והוצאות המימון שלה 500. שיעור המס של שתיהן 23%.',
    '<b>נדרש:</b> חשבו לכל אחת את הרווח הנקי, את שיעור הרווח התפעולי ואת שיעור הרווח הנקי.'],
   'שורות 7 עד 11 בעמודה B, וגוררים לעמודה C.',
   _NM, _NMS, [220, 110, 110], [1], given={'B2': 10000, 'C2': 10000, 'B3': 1200, 'C3': 1200, 'B4': 0, 'C4': 500, 'B5': 0.23, 'C5': 0.23},
   fmt={**{f'{c}{r}': 'num0' for c in 'BC' for r in (2, 3, 4, 7, 8, 9)}, 'B5': 'pct0', 'C5': 'pct0', **{f'{c}{r}': 'pct1' for c in 'BC' for r in (10, 11)}}, sty=_HD(),
   hints=['לפני מס: =B3-B4. מס: =B7*B5. נקי: =B7-B8.', 'שיעורים: =B3/B2 ו-=B9/B2. גוררים לעמודה C.'], remind='=B9/B2',
   traps={'C8': [('=C3*C5', 'המס מחושב על הרווח לפני מס, אחרי המימון: =C7*C5.')]},
   steps=[dict(cells={f'{c}{r}': _NMS[f'{c}{r}']}, note=f'{_NM["A" + str(r)]}, {"אבן הון" if c == "B" else "אבן חוב"}.') for r in (7, 8, 9, 10, 11) for c in 'BC'],
   qmc=RLIST([('רווח נקי', 'רווח לפני מס', 'פחות מס'), ('שיעור רווח נקי', 'רווח נקי', 'מכירות')]).replace('<i>חלקי</i> פחות', '<i>פחות</i>', 1),
   note=[('ans', 'אבן הון: רווח נקי 924, שיעור תפעולי 12%, נקי 9.2%. אבן חוב: 539, 12%, 5.4%.', 1),
         ('dg', 'טיפ: אותו שיעור תפעולי, שורה תחתונה שונה. הפער בין התפעולי לנקי מספר על מבנה ההון, כמו שראינו בהרצאה 2.', 2)],
   done='אבן הון 924 ו-9.2%; אבן חוב 539 ו-5.4%.', xtitle='אבן הון מול אבן חוב')

_G4 = '<div class="card"><table class="tbl2 cen"><tr><th>' + TX('רשת לבית ולגן') + '</th><th>2023</th><th>2024</th><th>2025</th><th>2026</th></tr>' + ''.join(
    f'<tr{" class=hl" if h else ""}><td>{TX(a)}</td>' + ''.join(f'<td class="amt">{TX(x)}</td>' for x in v) + '</tr>' for a, v, h in [
        ('שיעור רווח גולמי', ('31%', '32%', '33.5%', '35%'), True), ('שיעור רווח תפעולי', ('9%', '9%', '9.5%', '9%'), False), ('שיעור רווח נקי', ('6%', '6%', '6%', '6%'), True)]) + '</table></div>'
MC1('m-gmnm', 'שאלה אחת: גולמי עולה, נקי עומד', 'שיעור הרווח הגולמי של רשת לבית ולגן עולה כבר ארבע שנים, אבל שיעור הרווח הנקי לא זז. איזה הסבר אפשרי, ומה הוא אומר לבעלי המניות?*',
    ['החברה משקיעה בהוצאות שיווק, הכשרה וסניפים חדשים לטובת צמיחה. בטווח הקצר השיפור נבלע, ובטווח הארוך זו התפתחות חיובית', 'השיפור בגולמי מוכיח שהנקי ישתפר בשנה הבאה', 'הרשת הורידה מחירים', 'אין הסבר אפשרי: זו טעות בדוחות'], 0,
    'השיפור בגולמי נבלע בדרך לנקי, בהוצאות התפעול. אם אלה השקעות בצמיחה, ההתפתחות חיובית. אם זו עלייה בשכר המינימום או בשכר הדירה, שאינה בשליטת החברה, היא שלילית. ואם אלה בונוסים חריגים למנהלים, היא שנויה במחלוקת. הנתונים מצביעים איפה לחפש; התשובה בביאורים ובדוח הדירקטוריון.',
    side=_G4, foot=_FOOT)

_TX = {'A1': 'יבוא הדר, אלפי ש״ח', 'B1': 'שנת 2026', 'C1': 'שנת 2025', 'A2': 'מכירות', 'A3': 'רווח לפני מס', 'A4': 'מסים על ההכנסה', 'A6': 'רווח נקי', 'A7': 'שיעור מס אפקטיבי', 'A8': 'שיעור רווח נקי'}
_txf = lambda c: {f'{c}6': f'={c}3-{c}4', f'{c}7': f'={c}4/{c}3', f'{c}8': f'={c}6/{c}2'}
_TXS = {**_txf('B'), **_txf('C')}
QX('x-nm2', 'נסו לבד', 'יבוא הדר: הרווח הנקי השתפר. בזכות מה?',
   ['ליבוא הדר בע״מ מכירות של 10,000 אלפי ש״ח ורווח לפני מס של 1,000, בשתי השנים. המסים על ההכנסה היו 230 בשנת 2025, ו-150 בשנת 2026, אחרי שהחברה ניצלה הפסדים משנים קודמות לצורכי מס.',
    '<b>נדרש א:</b> חשבו לכל שנה את הרווח הנקי, את שיעור המס האפקטיבי ואת שיעור הרווח הנקי.', '<b>נדרש ב:</b> האם השיפור צפוי להימשך?'],
   'שורות 6 עד 8 בעמודה B, וגוררים לעמודה C.',
   _TX, _TXS, [230, 100, 100], [1], given={'B2': 10000, 'C2': 10000, 'B3': 1000, 'C3': 1000, 'B4': 150, 'C4': 230},
   fmt={**{f'{c}{r}': 'num0' for c in 'BC' for r in (2, 3, 4, 6)}, **{f'{c}{r}': 'pct1' for c in 'BC' for r in (7, 8)}}, sty=_HD(),
   hints=['רווח נקי: =B3-B4. מס אפקטיבי: =B4/B3.', 'שיעור נקי: =B6/B2. גוררים לעמודה C.'], remind='=B4/B3',
   steps=[dict(cells={f'{c}{r}': _TXS[f'{c}{r}']}, note=f'{_TX["A" + str(r)]}, {"2026" if c == "B" else "2025"}.') for r in (6, 7, 8) for c in 'BC'],
   qmc=RLIST([('שיעור מס אפקטיבי', 'מסים על ההכנסה', 'רווח לפני מס'), ('שיעור רווח נקי', 'רווח נקי', 'מכירות')])
   + MORE('תשובה לנדרש ב', ['הפעילות לא השתנתה: אותו רווח לפני מס. כל השיפור בנקי, מ-7.7% ל-8.5%, הוא המס.', 'הפסדים מועברים נגמרים. כשינוצלו כולם, שיעור המס יחזור לרמתו הרגילה, וגם השיעור הנקי.', 'לכן משווים גם את השיעור התפעולי ואת הרווח לפני מס, ולא רק את השורה התחתונה.']),
   note=[('ans', '2025: נקי 770, מס אפקטיבי 23%, שיעור נקי 7.7%. 2026: 850, 15%, 8.5%.', 1)],
   done='2025: 770, 23%, 7.7%. 2026: 850, 15%, 8.5%.', xtitle='יבוא הדר: שיעור מס אפקטיבי')
